<?php
namespace App\Http\Controllers;use App\Models\{Employee,EmployeeGoal,GoalType};use Illuminate\Http\Request;
class EmployeeGoalController extends Controller{public function index(Request $r){$q=EmployeeGoal::with(['employee','type'])->latest();$q->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('title','like',"%$v%")->orWhereHas('employee',fn($e)=>$e->where('name','like',"%$v%"))))->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->goal_type_id,fn($q,$v)=>$q->where('goal_type_id',$v))->when($r->status&&$r->status!=='All',fn($q)=>$q->where('status',$r->status));$counts=['All'=>EmployeeGoal::count(),'Not Started'=>EmployeeGoal::whereStatus('Not Started')->count(),'In Progress'=>EmployeeGoal::whereStatus('In Progress')->count(),'Completed'=>EmployeeGoal::whereStatus('Completed')->count()];return view('employee-goals.index',['goals'=>$q->paginate(10)->withQueryString(),'employees'=>Employee::orderBy('name')->get(),'types'=>GoalType::whereStatus(1)->orderBy('name')->get(),'counts'=>$counts]);}public function store(Request $r){EmployeeGoal::create($this->data($r));return back()->with('success','Employee goal created successfully.');}public function update(Request $r,EmployeeGoal $employeeGoal){$employeeGoal->update($this->data($r));return back()->with('success','Employee goal updated successfully.');}public function progress(Request $r,EmployeeGoal $employeeGoal){$d=$r->validate(['progress'=>'required|integer|min:0|max:100']);$d['status']=$d['progress']==100?'Completed':($d['progress']>0?'In Progress':'Not Started');$employeeGoal->update($d);return back()->with('success','Goal progress updated successfully.');}public function destroy(EmployeeGoal $employeeGoal){$employeeGoal->delete();return back()->with('success','Employee goal deleted successfully.');}private function data(Request $r){$d=$r->validate(['employee_id'=>'required|exists:employees,id','goal_type_id'=>'required|exists:goal_types,id','title'=>'required|string|min:2|max:191','description'=>'nullable|string|max:3000','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','target'=>'nullable|string|max:191','progress'=>'nullable|integer|min:0|max:100','status'=>'required|in:Not Started,In Progress,Completed']);$d['progress']=$d['progress']??0;if($d['progress']==100)$d['status']='Completed';return $d;}}
